class RiverGentleRoutingTest{static int steep(RiverCourse.Routing route,float[] h,int n){int count=0;for(int i=0;i<h.length;i++){int p=route.flow().parent()[i];if(p>=0&&(h[i]-h[p])/(8*Math.hypot(i%n-p%n,i/n-p/n))>.25)count++;}return count;}public static void main(String[]args){int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){double r=Math.hypot(x-64,z-64);h[z*n+x]=(float)(35+300*Math.exp(-r*r/900)+20*Math.sin(x/7.)*Math.sin(z/11.));}var e=new EnvironmentMap(h);var normal=RiverCourse.route(h,e,n,1024,62,()->false,false,1,19753);var gentle=RiverCourse.route(h,e,n,1024,62,()->false,false,1,19753,.15);for(int i=0;i<h.length;i++){int p=gentle.flow().parent()[i];if(p<0)continue;double slope=(h[i]-h[p])/(8*Math.hypot(i%n-p%n,i/n-p/n));if(slope>.150001)throw new AssertionError("Route crosses steep face: "+slope);if(h[i]>62&&RiverCourse.terrainSlope(h,n,i%n,i/n,8)>.300001)throw new AssertionError("Route crosses steep hillside");}int a=steep(normal,h,n),b=steep(gentle,h,n);if(a<20||b>=a*.85)throw new AssertionError("Steep routing not reduced: "+a+" / "+b);System.out.println("PASS: terrain slope preference reduces steep drainage links "+a+" -> "+b+" while preserving acyclic outlet routing");}}
